const { useState, useEffect } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = ['자바스크립트 입문', '리액트 시작하기', 'CSS 레이아웃'];

const Search = () => {
  const [keyword, setKeyword] = useState('');
  const [n, setN] = useState(0);

  const found = courses.filter((course) => course.includes(keyword));

  useEffect(() => {
    document.title = keyword === '' ? '코스 전체' : `코스 검색: ${keyword}`;
    document.querySelector('#outside').textContent = `바깥에 적었습니다: ${document.title}`;
    console.log('[keyword] 효과 · 문서 제목 =', document.title);
  }, [keyword]);

  useEffect(() => {
    console.log('[] 효과 · 처음 한 번만');
  }, []);

  useEffect(() => {
    console.log('배열 없음 효과 · 그릴 때마다');
  });

  return (
    <div className="panel">
      <label className="field" htmlFor="q">코스 검색</label>
      <input className="field__input" id="q" type="search" value={keyword}
        onChange={(event) => setKeyword(event.target.value)} />
      <p className="count">코스 {found.length}개</p>
      <div className="row">
        <button className="other" type="button" onClick={() => setN(n + 1)}>다른 상태 건드리기 ({n})</button>
      </div>
    </div>
  );
};

root.render(<Search />);

