const { useState, useEffect } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = ['자바스크립트 입문', '리액트 시작하기', 'CSS 레이아웃'];

const Search = () => {
  const [keyword, setKeyword] = useState('');

  const found = courses.filter((course) => course.includes(keyword));

  useEffect(() => {
    const label = keyword === '' ? '코스 전체' : `코스 검색: ${keyword}`;
    document.title = label;
    document.querySelector('#outside').textContent = label;
  }, [keyword]);

  return (
    <div className="panel">
      <label className="field" htmlFor="q">코스 검색</label>
